"use client";

import { useState, useEffect } from "react";
import { ToastContainer, toast } from "react-toastify";
import { motion } from "motion/react"; // Import Motion One
import "react-toastify/dist/ReactToastify.css";

const Roadmap = () => {
  const [progress, setProgress] = useState(0);

  // Handle lesson click (Toast + Progress Update)
  const handleLessonClick = (lessonIndex) => {
    toast.info(`Navigating to Lesson ${lessonIndex + 1}`, {
      position: "top-center",
    });
    setProgress(lessonIndex + 1); // update progress when a lesson is clicked
    localStorage.setItem("lessonProgress", lessonIndex + 1); // store progress in localStorage
  };

  useEffect(() => {
    // Retrieve progress from localStorage when the component mounts
    const savedProgress = localStorage.getItem("lessonProgress");
    if (savedProgress) {
      setProgress(parseInt(savedProgress));
    }
  }, []);

  const lessons = [
    { id: 1, title: "Lesson 1" },
    { id: 2, title: "Lesson 2" },
    { id: 3, title: "Lesson 3" },
    { id: 4, title: "Lesson 4" },
    { id: 5, title: "Lesson 5" },
    { id: 6, title: "Lesson 6" },
  ];

  return (
    <div className="roadmap-container">
      <ToastContainer />
      <div className="roadmap">
        <svg
          width="300"
          height="600"
          viewBox="0 0 300 600"
          xmlns="http://www.w3.org/2000/svg"
        >
          <defs>
            <linearGradient
              id="neonGradient"
              x1="0%"
              y1="0%"
              x2="100%"
              y2="100%"
            >
              <stop offset="0%" stop-color="#FF416C" />
              <stop offset="50%" stop-color="#7E51FF" />
              <stop offset="100%" stop-color="#2B65F9" />
            </linearGradient>

            <filter id="neonGlow" x="-50%" y="-50%" width="200%" height="200%">
              <feDropShadow
                dx="0"
                dy="0"
                stdDeviation="5"
                flood-color="#FF416C"
              />
              <feDropShadow
                dx="0"
                dy="0"
                stdDeviation="10"
                flood-color="#7E51FF"
              />
            </filter>
          </defs>

          {/* Neon Zigzag Path */}
          <motion.path
            d="M50 100 L150 50 L250 150 L150 250 L250 350 L150 450"
            stroke="url(#neonGradient)"
            stroke-width="6"
            fill="none"
            stroke-linecap="round"
            filter="url(#neonGlow)"
            initial={{ strokeDasharray: 0, strokeDashoffset: 50 }} // Initial state
            animate={{
              strokeDasharray: progress > 0 ? "50, 50" : "0, 50",
              strokeDashoffset: progress > 0 ? 0 : 50,
            }} // Animate based on progress
            transition={{ duration: 0.5 }}
          />

          {/* Roadmap Circles (Nodes) */}
          {lessons.map((lesson, index) => (
            <motion.circle
              key={lesson.id}
              cx={50 + index * 50} // Adjusting positions horizontally for lessons
              cy={100 + index * 100} // Adjusting positions vertically for lessons
              r="10"
              fill={index < progress ? "#7E51FF" : "#FF416C"} // Color the circle based on progress
              stroke="white"
              stroke-width="3"
              onClick={() => handleLessonClick(index)}
              aria-label={`Go to ${lesson.title}`}
              initial={{ scale: 1 }} // Initial scale for animation
              animate={{ scale: index < progress ? 1.2 : 1 }} // Increase size of completed lessons
              transition={{ duration: 0.3 }}
            />
          ))}
        </svg>
      </div>
    </div>
  );
};

export default Roadmap;
